withDescriptorSetLayout
  :: forall m r es1
   . (MonadUnliftIO m, AllExtends DescriptorSetLayoutCreateInfo es1, PokeChain es1)
  => Device
  -> DescriptorSetLayoutCreateInfo es1
  -> Maybe AllocationCallbacks
  -> (Outcome DescriptorSetLayout -> m r)
  -> m r
withDescriptorSetLayout device createInfo allocator cont_ =
  withRunInIO \run_ ->
    bracket
      (run_ (createDescriptorSetLayout device createInfo allocator))
      ( \o_ -> case o_ of
          Ok _ h_ -> run_ (destroyDescriptorSetLayout device h_ allocator)
          Err _ -> pure ()
      )
      (run_ . cont_)

